-- The tree runs guide ("Tree runs: the basic daily farming run"), written on the dev site, joins the live site as an
-- unpublished draft owned by the site owner (the staff member with the owner rank). The owner reviews and publishes it from
-- the staff guide workshop, so the publish is recorded like any other. Nothing is written when the site has no owner yet,
-- and a guide already saved under this ID is left as it is.
INSERT OR IGNORE INTO community_guides(id,author_id,title,draft,published,revision,updated_at,published_at,publisher_id)
SELECT 'tree-runs',discord_id,'Tree runs: the basic daily farming run','{"title":"Tree runs: the basic daily farming run","activity":"Farming","summary":"The five free tree patches and four fruit tree patches in one daily run, with teleports anyone can use, maps for every stop and what to plant at your level.","requirements":"15 Farming for oak trees and 27 for apple trees. Tree Gnome Village is recommended for spirit trees.","strategy":"Teleport to each patch, check the health of last run’s tree, plant a new sapling and pay the gardener. Trees first, then fruit trees.","equipment":{"head":null,"cape":null,"neck":null,"weapon":null,"body":null,"shield":null,"legs":null,"hands":null,"feet":null,"ring":null,"ammo":null},"inventory":["8007","8008","8009","8010","8011","952","5341","995","5371","5371","5371","5371","5371","5386","5497","5497","5497","5497",null,null,null,null,null,null,null,null,null,null],"requiredQuests":[],"requiredDiaries":[],"setups":[{"id":"early","name":"Early (30+)","equipment":{"head":null,"cape":null,"neck":null,"weapon":null,"body":null,"shield":null,"legs":null,"hands":null,"feet":null,"ring":null,"ammo":null},"inventory":["8007","8008","8009","8010","8011","952","5341","995","5371","5371","5371","5371","5371","5386","5497","5497","5497","5497",null,null,null,null,null,null,null,null,null,null],"stacks":{"7":{"quantity":300},"13":{"quantity":21,"noted":true}},"note":"Willows and bananas. Both gardeners take baskets of apples, noted in one slot. Bring a few hundred coins for the Brimhaven boat."},{"id":"mid","name":"Mid (60+)","equipment":{"head":null,"cape":null,"neck":null,"weapon":null,"body":null,"shield":null,"legs":null,"hands":null,"feet":null,"ring":null,"ammo":null},"inventory":["8007","8008","8009","8010","8011","952","5341","995","5373","5373","5373","5373","5373","6016","5501","5501","5501","5501","2114",null,null,null,null,null,null,null,null,null],"stacks":{"7":{"quantity":300},"13":{"quantity":50,"noted":true},"18":{"quantity":40,"noted":true}},"note":"Yews and papayas, with the cactus spines and pineapples noted. Bring a few hundred coins for the Brimhaven boat."},{"id":"high","name":"High (75+)","equipment":{"head":null,"cape":null,"neck":null,"weapon":null,"body":null,"shield":null,"legs":null,"hands":null,"feet":null,"ring":null,"ammo":null},"inventory":["8007","8008","8009","8010","8011","952","5341","995","5374","5374","5374","5374","5374","5974","5502","5502","5502","5502","5972",null,null,null,null,null,null,null,null,null],"stacks":{"7":{"quantity":300},"13":{"quantity":125,"noted":true},"18":{"quantity":60,"noted":true}},"note":"Magic trees and palms, with the coconuts and papaya fruit noted. Bring a few hundred coins for the Brimhaven boat."}],"requiredItems":[{"id":"952","quantity":1},{"id":"5341","quantity":1}],"requiredSkills":[{"skill":"Farming","level":15}],"recommendedSkills":[{"skill":"Farming","level":75}],"requiredOther":[{"label":"Tree Gnome Village (recommended) for spirit trees","itemId":null,"icon":"spirit"}],"blocks":[{"id":"overview","kind":"text","text":"Overview","style":"heading","tone":"default"},{"id":"overview-body","kind":"text","text":"The simplest daily tree run: the five free tree patches and four fruit tree patches, using teleports anyone can cast or buy as tablets. Plant, pay the gardener to protect each tree, and come back next run to check its health for most of the XP. Every tree you check is also a roll at the [[Tangleroot]] pet.","style":"body","tone":"default"},{"id":"requirements","kind":"requirements"},{"id":"items","kind":"text","text":"What to bring","style":"heading","tone":"default"},{"id":"items-body","kind":"text","text":"Pick the tab for your Farming level. Each one is a full run; hover any item to see what it is.","style":"body","tone":"default"},{"id":"items-cols","kind":"columns","split":"1:1","columns":[{"id":"bag","kind":"inventory","setupId":"early","setupIds":["early","mid","high"]},{"id":"cost","kind":"costs","title":"Level","rows":[{"itemId":"5371","label":"Early (30+)","parts":[{"itemId":"5371","quantity":5},{"itemId":"5497","quantity":4},{"itemId":"5386","quantity":21}]},{"itemId":"5373","label":"Mid (60+)","parts":[{"itemId":"5373","quantity":5},{"itemId":"5501","quantity":4},{"itemId":"6016","quantity":50},{"itemId":"2114","quantity":40}]},{"itemId":"5374","label":"High (75+)","parts":[{"itemId":"5374","quantity":5},{"itemId":"5502","quantity":4},{"itemId":"5974","quantity":125},{"itemId":"5972","quantity":60}]}],"per":"run"}]},{"id":"order","kind":"text","text":"The route","style":"heading","tone":"default"},{"id":"order-body","kind":"text","text":"Trees first, then fruit trees. Trees take about 8 hours (magic) and fruit trees about 16 hours, so one run a day keeps every patch busy. Tree Gnome Village unlocks the spirit trees that make the gnome patches quick.","style":"body","tone":"default"},{"id":"s1","kind":"text","text":"1. Varrock: tree patch","style":"heading","tone":"default"},{"id":"map-1","kind":"map","title":"","x":3220,"y":3442,"plane":0,"zoom":9,"pins":[{"x":3212,"y":3424,"plane":0,"label":"Varrock teleport","kind":"teleport","text":"Teleport to Varrock."},{"x":3229,"y":3459,"plane":0,"label":"Tree patch","kind":"stop","text":"Walk north-east to the Varrock Castle garden. Check health, chop the old tree, plant and pay the gardener."}]},{"id":"s2","kind":"text","text":"2. Lumbridge: tree patch","style":"heading","tone":"default"},{"id":"map-2","kind":"map","title":"","x":3208,"y":3224,"plane":0,"zoom":9,"pins":[{"x":3222,"y":3218,"plane":0,"label":"Lumbridge teleport","kind":"teleport","text":"Teleport to Lumbridge (the free Home Teleport works too)."},{"x":3193,"y":3231,"plane":0,"label":"Tree patch","kind":"stop","text":"Just west of the castle. Check, chop, plant and pay."}]},{"id":"s3","kind":"text","text":"3. Falador: tree patch","style":"heading","tone":"default"},{"id":"map-3","kind":"map","title":"","x":2984,"y":3376,"plane":0,"zoom":9,"pins":[{"x":2965,"y":3379,"plane":0,"label":"Falador teleport","kind":"teleport","text":"Teleport to Falador."},{"x":3004,"y":3373,"plane":0,"label":"Tree patch","kind":"stop","text":"Walk south-east into Falador Park. Check, chop, plant and pay."}]},{"id":"s4","kind":"text","text":"4. Taverley: tree patch","style":"heading","tone":"default"},{"id":"map-4","kind":"map","title":"","x":2950,"y":3408,"plane":0,"zoom":8,"pins":[{"x":2965,"y":3379,"plane":0,"label":"From Falador","kind":"stop","text":"Run north-west through the gate to Taverley."},{"x":2936,"y":3438,"plane":0,"label":"Tree patch","kind":"stop","text":"In the south of the village. Check, chop, plant and pay."}]},{"id":"s5","kind":"text","text":"5. Gnome Stronghold: tree and fruit tree patches","style":"heading","tone":"default"},{"id":"map-5","kind":"map","title":"","x":2456,"y":3430,"plane":0,"zoom":8,"pins":[{"x":2461,"y":3444,"plane":0,"label":"Spirit tree","kind":"teleport","text":"Take the spirit tree here, or use a [[Royal seed pod]]."},{"x":2436,"y":3415,"plane":0,"label":"Tree patch","kind":"stop","text":"South of the Grand Tree. Check, chop, plant and pay."},{"x":2475,"y":3446,"plane":0,"label":"Fruit tree patch","kind":"stop","text":"East of the Grand Tree. Check, plant and pay."}]},{"id":"s6","kind":"text","text":"6. Tree Gnome Village: fruit tree patch","style":"heading","tone":"default"},{"id":"map-6","kind":"map","title":"","x":2516,"y":3175,"plane":0,"zoom":9,"pins":[{"x":2542,"y":3170,"plane":0,"label":"Spirit tree","kind":"teleport","text":"Take the spirit tree to Tree Gnome Village."},{"x":2490,"y":3180,"plane":0,"label":"Fruit tree patch","kind":"stop","text":"Just north-west of the spirit tree, outside the maze. Check, plant and pay."}]},{"id":"s7","kind":"text","text":"7. Catherby: fruit tree patch","style":"heading","tone":"default"},{"id":"map-7","kind":"map","title":"","x":2808,"y":3456,"plane":0,"zoom":8,"pins":[{"x":2757,"y":3478,"plane":0,"label":"Camelot teleport","kind":"teleport","text":"Teleport to Camelot."},{"x":2860,"y":3433,"plane":0,"label":"Fruit tree patch","kind":"stop","text":"Run east into Catherby, past the beach farm. Check, plant and pay."}]},{"id":"s8","kind":"text","text":"8. Brimhaven: fruit tree patch","style":"heading","tone":"default"},{"id":"map-8","kind":"map","title":"","x":2716,"y":3258,"plane":0,"zoom":7,"pins":[{"x":2661,"y":3305,"plane":0,"label":"Ardougne teleport","kind":"teleport","text":"Teleport to Ardougne."},{"x":2675,"y":3275,"plane":0,"label":"Boat to Brimhaven","kind":"stop","text":"Walk south to the docks and pay 30 coins to sail."},{"x":2772,"y":3225,"plane":0,"label":"Arrive in Brimhaven","kind":"teleport","text":"Step off at the Brimhaven dock.","via":"Boat"},{"x":2764,"y":3212,"plane":0,"label":"Fruit tree patch","kind":"stop","text":"A short walk west of the dock. Check, plant and pay."}]},{"id":"extras","kind":"text","text":"9. Farming Guild (extra): tree and fruit tree patches","style":"heading","tone":"default"},{"id":"map-x","kind":"map","title":"","x":1240,"y":3745,"plane":0,"zoom":9,"pins":[{"x":1249,"y":3718,"plane":0,"label":"Skills necklace teleport","kind":"teleport","text":"Teleport straight into the Farming Guild with a [[Skills necklace]]. Add the guild to the end of the run once you have the levels."},{"x":1232,"y":3736,"plane":0,"label":"Tree patch (65 Farming)","kind":"stop","text":"In the guild''s intermediate tier, north-west of the entrance. Check, chop, plant and pay."},{"x":1243,"y":3759,"plane":0,"label":"Fruit tree patch (85 Farming)","kind":"stop","text":"Further north, in the advanced tier. Check, plant and pay."}]},{"id":"divider","kind":"divider"},{"id":"pet","kind":"text","text":"Tangleroot","style":"heading","tone":"default"},{"id":"pet-cols","kind":"columns","split":"1:1","columns":[{"id":"pet-body","kind":"text","text":"Each tree you check rolls for [[Tangleroot]], and the chance improves with your Farming level. With five magic trees and four palm trees this run is about 1 in 747 runs at 99. Track yours on your Spooned profile with the Tree runs method.","style":"body","tone":"default"},{"id":"odds","kind":"odds","name":"Tangleroot","rate":747,"count":747,"unit":"runs"}]}]}',NULL,1,'2026-11-03T00:00:00.000Z',NULL,NULL
